export function Header(props: PropsRuntime<'conversation.header.leading'> & ViewProps) {
  const { t, loadBalance, openAPI } = props
  const [balance, setBalance] = useState<Balance>()
  const [error, setError] = useState('')
  const [busy, setBusy] = useState(false)
  const refresh = async () => { setBusy(true); try { setBalance(await loadBalance()); setError('') } catch(e) { setError(String(e instanceof Error ? e.message : e)) } finally { setBusy(false) } }
  useEffect(() => { void refresh(); const id = window.setInterval(() => { if (document.visibilityState === 'visible') void refresh() }, 30_000); return () => window.clearInterval(id) }, [loadBalance])
  return <div className={css.apiGroup}><Tooltip label={`${t('balanceHint')} ${error}`}><button className={css.balance} onClick={() => void refresh()} disabled={busy}>{busy ? t('querying') : balance ? balance.balance_infos.map(b => `${b.currency === 'CNY' ? '¥' : '$'}${b.total_balance}`).join(' / ') : t('noBalance')}<small>{balance ? new Date(balance.checkedAt).toLocaleTimeString() : 'DeepSeek API'}</small></button></Tooltip><button className={css.apiButton} onClick={openAPI}>{t('api')}</button></div>
}
function errorMessage(e: unknown) { return e instanceof Error ? e.message : String(e) }
